import { Router, type Request, type Response } from "express";
import {
  createNote,
  deleteNote,
  getNote,
  normalizeTag,
  normalizeTags,
  queryNotes,
  updateNote,
} from "../store/notesStore.js";

export const notesRouter = Router();

const hasOwn = (value: object, key: string): boolean =>
  Object.prototype.hasOwnProperty.call(value, key);

function parsePositivePage(value: unknown): number | string {
  if (typeof value !== "string" || !/^\d+$/.test(value)) {
    return "page must be a positive integer";
  }
  const page = Number(value);
  if (!Number.isSafeInteger(page) || page < 1) {
    return "page must be a positive integer";
  }
  return page;
}

function parsePageSize(value: unknown): number | string {
  if (typeof value !== "string" || !/^\d+$/.test(value)) {
    return "pageSize must be an integer between 1 and 100";
  }
  const pageSize = Number(value);
  if (!Number.isInteger(pageSize) || pageSize < 1 || pageSize > 100) {
    return "pageSize must be an integer between 1 and 100";
  }
  return pageSize;
}

notesRouter.get("/", (req: Request, res: Response) => {
  const query = req.query as Record<string, unknown>;
  let tag: string | undefined;
  let q: string | undefined;
  let page = 1;
  let pageSize = 20;

  if (hasOwn(query, "tag")) {
    if (typeof query.tag !== "string") {
      res.status(400).json({ error: "tag must be a single string" });
      return;
    }
    const normalizedTag = normalizeTag(query.tag);
    if (!normalizedTag.ok) {
      res.status(400).json({ error: "tag must be a non-empty string of at most 32 characters" });
      return;
    }
    tag = normalizedTag.tag;
  }

  if (hasOwn(query, "q")) {
    if (typeof query.q !== "string") {
      res.status(400).json({ error: "q must be a single string" });
      return;
    }
    const trimmed = query.q.trim();
    if (trimmed.length > 0) {
      q = trimmed.normalize("NFC").toLowerCase().normalize("NFC");
    }
  }

  if (hasOwn(query, "page")) {
    const parsedPage = parsePositivePage(query.page);
    if (typeof parsedPage === "string") {
      res.status(400).json({ error: parsedPage });
      return;
    }
    page = parsedPage;
  }

  if (hasOwn(query, "pageSize")) {
    const parsedPageSize = parsePageSize(query.pageSize);
    if (typeof parsedPageSize === "string") {
      res.status(400).json({ error: parsedPageSize });
      return;
    }
    pageSize = parsedPageSize;
  }

  const result = queryNotes({ tag, q, page, pageSize });
  const totalPages = Math.ceil(result.total / pageSize);
  res.json({ items: result.items, page, pageSize, total: result.total, totalPages });
});

notesRouter.get("/:id", (req: Request, res: Response) => {
  const note = getNote(req.params.id);
  if (!note) {
    res.status(404).json({ error: "Note not found" });
    return;
  }
  res.json(note);
});

notesRouter.post("/", (req: Request, res: Response) => {
  const requestBody = req.body ?? {};
  const { title, body } = requestBody;
  if (typeof title !== "string" || typeof body !== "string") {
    res.status(400).json({ error: "title and body are required strings" });
    return;
  }

  let tags: string[] = [];
  if (hasOwn(requestBody, "tags")) {
    const normalizedTags = normalizeTags(requestBody.tags);
    if (!normalizedTags.ok) {
      res.status(400).json({ error: normalizedTags.error });
      return;
    }
    tags = normalizedTags.tags;
  }
  res.status(201).json(createNote(title, body, tags));
});

notesRouter.patch("/:id", (req: Request, res: Response) => {
  const requestBody = req.body;
  if (requestBody === null || typeof requestBody !== "object" || Array.isArray(requestBody)) {
    res.status(400).json({ error: "request body must be an object" });
    return;
  }

  const hasTitle = hasOwn(requestBody, "title");
  const hasBody = hasOwn(requestBody, "body");
  const hasTags = hasOwn(requestBody, "tags");
  if (
    (hasTitle && typeof requestBody.title !== "string") ||
    (hasBody && typeof requestBody.body !== "string")
  ) {
    res.status(400).json({ error: "title and body must be strings" });
    return;
  }

  const patch: { title?: string; body?: string; tags?: string[] } = {};
  if (hasTitle) {
    patch.title = requestBody.title;
  }
  if (hasBody) {
    patch.body = requestBody.body;
  }
  if (hasTags) {
    const normalizedTags = normalizeTags(requestBody.tags);
    if (!normalizedTags.ok) {
      res.status(400).json({ error: normalizedTags.error });
      return;
    }
    patch.tags = normalizedTags.tags;
  }

  const note = updateNote(req.params.id, patch);
  if (!note) {
    res.status(404).json({ error: "Note not found" });
    return;
  }
  res.json(note);
});

notesRouter.delete("/:id", (req: Request, res: Response) => {
  const deleted = deleteNote(req.params.id);
  if (!deleted) {
    res.status(404).json({ error: "Note not found" });
    return;
  }
  res.status(204).end();
});

export interface Note {
  id: string;
  title: string;
  body: string;
  tags: string[];
  createdAt: string;
}

const notes = new Map<string, Note>();
let nextId = 1;

const TAG_ERROR = "each tag must be a non-empty string of at most 32 characters";

export function normalizeTag(
  input: unknown,
): { ok: true; tag: string } | { ok: false; error: string } {
  if (typeof input !== "string") {
    return { ok: false, error: TAG_ERROR };
  }

  const trimmed = input.trim().normalize("NFC");
  if (trimmed.length === 0) {
    return { ok: false, error: TAG_ERROR };
  }

  const tag = trimmed.toLowerCase().normalize("NFC");
  if ([...tag].length > 32) {
    return { ok: false, error: TAG_ERROR };
  }

  return { ok: true, tag };
}

export function normalizeTags(
  input: unknown,
): { ok: true; tags: string[] } | { ok: false; error: string } {
  if (!Array.isArray(input)) {
    return { ok: false, error: "tags must be an array" };
  }
  if (input.length > 20) {
    return { ok: false, error: "tags must contain at most 20 items" };
  }

  const tags: string[] = [];
  const seen = new Set<string>();
  for (const value of input) {
    const normalized = normalizeTag(value);
    if (!normalized.ok) {
      return normalized;
    }
    if (!seen.has(normalized.tag)) {
      seen.add(normalized.tag);
      tags.push(normalized.tag);
    }
  }

  return { ok: true, tags };
}

export function listNotes(): Note[] {
  return Array.from(notes.values());
}

export function getNote(id: string): Note | undefined {
  return notes.get(id);
}

export function createNote(title: string, body: string, tags: string[] = []): Note {
  const note: Note = {
    id: String(nextId++),
    title,
    body,
    tags: [...tags],
    createdAt: new Date().toISOString(),
  };
  notes.set(note.id, note);
  return note;
}

export function updateNote(
  id: string,
  patch: { title?: string; body?: string; tags?: string[] },
): Note | undefined {
  const note = notes.get(id);
  if (!note) {
    return undefined;
  }

  if (patch.title !== undefined) {
    note.title = patch.title;
  }
  if (patch.body !== undefined) {
    note.body = patch.body;
  }
  if (patch.tags !== undefined) {
    note.tags = [...patch.tags];
  }
  return note;
}

function searchable(value: string): string {
  return value.normalize("NFC").toLowerCase().normalize("NFC");
}

export function queryNotes(opts: {
  tag?: string;
  q?: string;
  page: number;
  pageSize: number;
}): { items: Note[]; total: number } {
  const needle = opts.q === undefined ? undefined : searchable(opts.q);
  const filtered = Array.from(notes.values()).filter((note) => {
    if (opts.tag !== undefined && !note.tags.includes(opts.tag)) {
      return false;
    }
    if (
      needle !== undefined &&
      !searchable(note.title).includes(needle) &&
      !searchable(note.body).includes(needle)
    ) {
      return false;
    }
    return true;
  });

  filtered.sort((a, b) => Number(a.id) - Number(b.id));
  const total = filtered.length;
  const totalPages = Math.ceil(total / opts.pageSize);
  if (opts.page > totalPages) {
    return { items: [], total };
  }

  const start = (opts.page - 1) * opts.pageSize;
  return {
    items: filtered.slice(start, start + opts.pageSize),
    total,
  };
}

export function deleteNote(id: string): boolean {
  return notes.delete(id);
}

import { describe, expect, it } from "vitest";
import request from "supertest";
import { app } from "../src/server.js";

async function createNote(title: string, body: string, tags?: unknown) {
  const payload: { title: string; body: string; tags?: unknown } = { title, body };
  if (tags !== undefined) {
    payload.tags = tags;
  }
  return request(app).post("/notes").send(payload);
}

describe("Notes API", () => {
  it("creates and lists a note in the pagination envelope", async () => {
    const created = await createNote("Buy milk", "2%, from the corner store");

    expect(created.status).toBe(201);
    expect(created.body.title).toBe("Buy milk");
    expect(created.body.tags).toEqual([]);

    const listed = await request(app).get("/notes");
    expect(listed.status).toBe(200);
    expect(listed.body.items.some((note: { id: string }) => note.id === created.body.id)).toBe(
      true,
    );
    expect(listed.body.page).toBe(1);
    expect(listed.body.pageSize).toBe(20);
  });

  it("normalizes tags and enforces tag input validation", async () => {
    const created = await createNote("Tagged", "body", [" Work ", "work", "Home"]);
    expect(created.status).toBe(201);
    expect(created.body.tags).toEqual(["work", "home"]);

    for (const tags of [null, ["ok", ""], "work"]) {
      const response = await createNote("Invalid tags", "body", tags);
      expect(response.status).toBe(400);
    }
  });

  it("enforces tag count and Unicode length limits before deduplication", async () => {
    const valid = await createNote("Limits", "body", [
      ...Array.from({ length: 19 }, (_, index) => `tag-${index}`),
      "😀".repeat(32),
    ]);
    expect(valid.status).toBe(201);

    const tooLong = await createNote("Too long", "body", ["😀".repeat(33)]);
    expect(tooLong.status).toBe(400);

    const tooMany = await createNote(
      "Too many",
      "body",
      Array.from({ length: 21 }, () => "duplicate"),
    );
    expect(tooMany.status).toBe(400);
  });

  it("updates tags without changing other fields and supports clearing them", async () => {
    const created = await createNote("Original title", "Original body", ["old"]);
    const updated = await request(app)
      .patch(`/notes/${created.body.id}`)
      .send({ tags: [" New ", "new"] });

    expect(updated.status).toBe(200);
    expect(updated.body.title).toBe("Original title");
    expect(updated.body.body).toBe("Original body");
    expect(updated.body.tags).toEqual(["new"]);

    const noOp = await request(app).patch(`/notes/${created.body.id}`).send({});
    expect(noOp.status).toBe(200);
    expect(noOp.body).toEqual(updated.body);

    const cleared = await request(app).patch(`/notes/${created.body.id}`).send({ tags: [] });
    expect(cleared.status).toBe(200);
    expect(cleared.body.tags).toEqual([]);

    const invalid = await request(app).patch(`/notes/${created.body.id}`).send({ tags: null });
    expect(invalid.status).toBe(400);

    const missing = await request(app).patch("/notes/does-not-exist").send({});
    expect(missing.status).toBe(404);
  });

  it("validates PATCH bodies before looking up the note", async () => {
    for (const body of ["null", "[]", '"invalid"']) {
      const response = await request(app)
        .patch("/notes/does-not-exist")
        .set("Content-Type", "application/json")
        .send(body);
      expect(response.status).toBe(400);
      expect(response.body.error).toBe("request body must be an object");
    }

    const malformed = await request(app)
      .patch("/notes/does-not-exist")
      .send({ title: 123 });
    expect(malformed.status).toBe(400);
    expect(malformed.body.error).toBe("title and body must be strings");
  });

  it("filters tags case-insensitively and rejects invalid tag filters", async () => {
    const created = await createNote("Filter target", "body", ["Work"]);
    await createNote("Other filter note", "body", ["personal"]);

    const filtered = await request(app).get("/notes").query({ tag: "WoRk" });
    expect(filtered.status).toBe(200);
    expect(filtered.body.items.map((note: { id: string }) => note.id)).toContain(created.body.id);

    for (const tag of ["", "   "]) {
      const invalid = await request(app).get("/notes").query({ tag });
      expect(invalid.status).toBe(400);
      expect(invalid.body.error).toBe("tag must be a non-empty string of at most 32 characters");
    }
  });

  it("searches title and body with Unicode-aware case normalization", async () => {
    const titleMatch = await createNote("Needle in title", "unrelated");
    const bodyMatch = await createNote("unrelated", "NEEDLE in body");
    const composed = await createNote("Cafe\u0301", "unrelated");
    const boundary = await createNote("abc", "def");

    const titleResults = await request(app).get("/notes").query({ q: "NEEDLE" });
    expect(titleResults.body.items.map((note: { id: string }) => note.id)).toEqual(
      expect.arrayContaining([titleMatch.body.id, bodyMatch.body.id]),
    );

    const unicodeResults = await request(app).get("/notes").query({ q: "CAFÉ" });
    expect(unicodeResults.body.items.map((note: { id: string }) => note.id)).toContain(
      composed.body.id,
    );

    const boundaryResults = await request(app).get("/notes").query({ q: "c def" });
    expect(boundaryResults.body.items.map((note: { id: string }) => note.id)).not.toContain(
      boundary.body.id,
    );

    for (const q of ["", "   "]) {
      const withoutSearch = await request(app).get("/notes").query({ q });
      expect(withoutSearch.body.total).toBeGreaterThan(0);
    }
  });

  it("combines tag, search, and pagination filters", async () => {
    const notes = await Promise.all([
      createNote("Combined one", "other", ["Combined"]),
      createNote("Combined two", "TARGET", ["Combined"]),
      createNote("Combined three", "other", ["Combined"]),
      createNote("Combined four", "target", ["Combined"]),
      createNote("Combined five", "other", ["Combined"]),
    ]);

    const response = await request(app)
      .get("/notes")
      .query({ tag: "combined", q: "target", page: "2", pageSize: "1" });

    expect(response.status).toBe(200);
    expect(response.body.total).toBe(2);
    expect(response.body.totalPages).toBe(2);
    expect(response.body.items).toHaveLength(1);
    expect(response.body.items[0].id).toBe(notes[3].body.id);
  });

  it("paginates in numeric id order and returns truthful empty pages", async () => {
    const created = await Promise.all(
      Array.from({ length: 5 }, (_, index) => createNote(`Pagination ${index}`, "body", ["paging"])),
    );
    const expectedIds = created.map((response) => response.body.id);

    const pageOne = await request(app).get("/notes").query({ tag: "paging", page: 1, pageSize: 2 });
    const pageTwo = await request(app).get("/notes").query({ tag: "paging", page: 2, pageSize: 2 });
    expect(pageOne.body.total).toBe(5);
    expect(pageOne.body.totalPages).toBe(3);
    expect(pageOne.body.items.map((note: { id: string }) => note.id)).toEqual(expectedIds.slice(0, 2));
    expect(pageTwo.body.items.map((note: { id: string }) => note.id)).toEqual(expectedIds.slice(2, 4));
    expect(pageOne.body.items.map((note: { id: string }) => note.id)).not.toEqual(
      expect.arrayContaining(pageTwo.body.items.map((note: { id: string }) => note.id)),
    );

    const pastEnd = await request(app)
      .get("/notes")
      .query({ tag: "paging", page: 99, pageSize: 2 });
    expect(pastEnd.status).toBe(200);
    expect(pastEnd.body.page).toBe(99);
    expect(pastEnd.body.items).toEqual([]);
    expect(pastEnd.body.total).toBe(5);

    const noMatches = await request(app).get("/notes").query({ tag: "no-such-tag" });
    expect(noMatches.body).toMatchObject({ page: 1, total: 0, totalPages: 0, items: [] });
  });

  it("rejects invalid pagination values", async () => {
    for (const page of ["0", "abc", "1.5", "1e2", "9007199254740992"]) {
      const response = await request(app).get("/notes").query({ page });
      expect(response.status).toBe(400);
      expect(response.body.error).toBe("page must be a positive integer");
    }

    for (const pageSize of ["0", "101", "1.5", "1e2"]) {
      const response = await request(app).get("/notes").query({ pageSize });
      expect(response.status).toBe(400);
      expect(response.body.error).toBe("pageSize must be an integer between 1 and 100");
    }
  });

  it("rejects repeated and non-scalar query parameters", async () => {
    for (const key of ["tag", "q", "page", "pageSize"]) {
      const repeated = await request(app).get("/notes").query({ [key]: ["a", "b"] });
      expect(repeated.status).toBe(400);
      expect(repeated.body.error).toBe(
        key === "tag"
          ? "tag must be a single string"
          : key === "q"
            ? "q must be a single string"
            : key === "page"
              ? "page must be a positive integer"
              : "pageSize must be an integer between 1 and 100",
      );

      const structured = await request(app).get("/notes").query({ [`${key}[value]`]: "x" });
      expect(structured.status).toBe(400);
    }
  });

  it("returns 404 for a missing note", async () => {
    const res = await request(app).get("/notes/does-not-exist");
    expect(res.status).toBe(404);
  });

  it("rejects a note missing title or body", async () => {
    const res = await request(app).post("/notes").send({ title: "No body" });
    expect(res.status).toBe(400);
  });
});

